{
  "requirement_items": [
    {
      "section": "4.7.2.1",
      "label": "[REQ-1-OAD-7050]",
      "text": "The Observatory Safety System shall be implemented as an independent PLC based system whose operation does not rely on the availability of any other sub-systems other than power.",
      "id": "REQ-1-OAD-7050"
    },
    {
      "section": "4.7.2.1",
      "label": "[REQ-1-OAD-7052]",
      "text": "The OSS shall provide different operational modes that support:\n� Observing Operations\n� Maintenance Operations\n� Fault and Interlock Recovery",
      "id": "REQ-1-OAD-7052"
    },
    {
      "section": "4.7.2.1",
      "label": "[REQ-1-OAD-7051]",
      "text": "The OSS shall provide fault, interlock and emergency stop monitoring and control in a manner consistent with the TMT System Level Hazard Analysis Document (AD37).",
      "id": "REQ-1-OAD-7051"
    },
    {
      "section": "4.7.2.1",
      "label": "[REQ-1-OAD-7053]",
      "text": "The OSS shall be able to detect hazardous faults or conditions that are not associated with a particular sub-system.",
      "id": "REQ-1-OAD-7053"
    },
    {
      "section": "4.7.2.1",
      "label": "[REQ-1-OAD-7054]",
      "text": "The OSS shall have the capability to detect earthquakes and respond by implementing and enforcing any interlocks on sub-systems that are required to maintain safety under these conditions.",
      "id": "REQ-1-OAD-7054"
    },
    {
      "section": "4.7.2.1",
      "label": "[REQ-1-OAD-7059]",
      "text": "The OSS shall have a Hardware Control Daemon (HCD) that allows OSS information to be communicated via the common services framework.",
      "id": "REQ-1-OAD-7059"
    },
    {
      "section": "4.7.2.1",
      "label": "[REQ-1-OAD-7061]",
      "text": "The OSS shall include a simple user interface accessible via both a PanelView and the ESW via the OSS HCD (Hardware Control Daemon), that displays an indication of the state of the safety system and allows the user to:\n� Reset interlocks\n� Query which sub-systems have generated interlock requests\n� Query which sub-systems are interlocked via interlock demand signals",
      "id": "REQ-1-OAD-7061"
    },
    {
      "section": "4.7.2.1",
      "label": "[REQ-1-OAD-7062]",
      "text": "The OSS shall provide an indication to the Data Management System (DMS) and the Executive Software (ESW) of the status of any interlocks raised by either the OSS Global Safety Controller (GSC) or any sub-system Local Safety Controller (LSC).",
      "id": "REQ-1-OAD-7062"
    },
    {
      "section": "4.7.2.1",
      "label": "[REQ-1-OAD-7063]",
      "text": "Whenever the OSS alerts the ESW and/or the DMS to an interlock event, it shall include in the notification any relevant engineering information pertaining to the interlock condition (e.g. the sub-system that raised the interlock request, the time the event occurred, etc.).",
      "id": "REQ-1-OAD-7063"
    },
    {
      "section": "4.7.2.1",
      "label": "[REQ-1-OAD-7064]",
      "text": "The OSS shall provide and control independent audible and visual warning devices located throughout the summit facility as per the Hazard Analysis.",
      "id": "REQ-1-OAD-7064"
    },
    {
      "section": "4.7.2.2",
      "label": "[REQ-1-OAD-7065]",
      "text": "The OSS shall continuously monitor the fault states of all connected devices and subsystems and, upon detection of faults or hazards, impose appropriate interlocks on other connected subsystems per the TMT System Level Hazard Analysis (AD37).",
      "id": "REQ-1-OAD-7065"
    },
    {
      "section": "4.7.2.2",
      "label": null,
      "text": "This implies that all subsystems shall be able to receive an interlock demand signal from the OSS and provide an interlock event signal to it, transmitted exclusively via the EtherNet/IP safety fieldbus.",
      "id": null
    },
    {
      "section": "4.7.2.2",
      "label": "[REQ-1-OAD-7080]",
      "text": "The OSS shall have the capability to latch an interlock until it is manually reset via the user interface.",
      "id": "REQ-1-OAD-7080"
    },
    {
      "section": "4.7.2.2",
      "label": "[REQ-1-OAD-7081]",
      "text": "The re-setting of sub-system interlocks shall be via a secure interface to the global safety controller.",
      "id": "REQ-1-OAD-7081"
    },
    {
      "section": "4.7.2.2",
      "label": "[REQ-1-OAD-7085]",
      "text": "Reset of the interlock demands generated by the OSS shall only be possible provided the interlock request is no longer present.",
      "id": "REQ-1-OAD-7085"
    },
    {
      "section": "4.7.2.2",
      "label": "[REQ-1-OAD-7086]",
      "text": "The OSS shall ensure that the system enters a safe state on system startup or if there is a power or network failure.",
      "id": "REQ-1-OAD-7086"
    },
    {
      "section": "4.7.2.2",
      "label": "[REQ-1-OAD-7088]",
      "text": "Maintenance and checkout of the OSS shall require no more than 20 hours per year.",
      "id": "REQ-1-OAD-7088"
    },
    {
      "section": "4.7.2.3",
      "label": "[REQ-1-OAD-7100]",
      "text": "The OSS shall implement an emergency stop (E-Stop) system that operates without reliance on any other sub-system.",
      "id": "REQ-1-OAD-7100"
    },
    {
      "section": "4.7.2.3",
      "label": "[REQ-1-OAD-7105]",
      "text": "The OSS shall be responsible for continuously monitoring all emergency stops throughout the observatory. In the event of an emergency stop being triggered, it is responsible for ensuring that appropriate action is taken to enforce safety and reduce risk.",
      "id": "REQ-1-OAD-7105"
    }
  ],
